//! `ferx --licenses` (#3183): the license texts and notices the `ferx` binary
//! has to carry.
//!
//! The ferx-cli source is MIT, but the binary statically links `ferx-search`
//! (LGPL-3.0-or-later) and NLopt's Luksan routines (LGPL-2.1-or-later), so it
//! ships those licenses, the notices of every linked crate
//! (`THIRD-PARTY-NOTICES.txt`, generated by `tools/third-party-notices.py`) and
//! the means to rebuild it with a modified `ferx-search`.

/// The summary that heads the output. `{version}` is this build's version.
const SUMMARY: &str = "\
ferx {version}: licenses and notices
====================================

This program is built from four crates of https://github.com/FeRx-NLME/ferx-core:

  ferx-core, ferx-tools, ferx-cli   MIT License (text below)
  ferx-search                       GNU LGPL, version 3 or later (texts below);
                                    linked unless built without the default
                                    `search` feature

ferx-search notice:
  Copyright (c) 2026 the FeRx core developer team (the ferx contributors).
  Parts of this crate follow the behaviour of Pharmpy
  (https://github.com/pharmpy/pharmpy, LGPL-3.0-or-later, (c) the Pharmpy
  authors) and were written with its source as a reference.
  Releases of this code inside ferx-tools, up to and including 0.4.0, are MIT.

ferx-search is statically linked into this program. You may rebuild the
program with a modified ferx-search. The complete source of this version is
the git tag v{version} of the repository above (and each crate is published on
crates.io at version {version}). Edit crates/ferx-search, then build with

  cargo build --release --locked -p ferx-cli

which writes target/release/ferx. https://ferx-nlme.org/ferx-core/license.html
has the details.

The program also links third-party crates, including the NLopt C library,
whose Luksan routines are LGPL-2.1-or-later; their notices follow the license
texts.
";

const MIT: &str = include_str!("../LICENSE");
const LGPL_3: &str = include_str!("../licenses/LGPL-3.0.txt");
const GPL_3: &str = include_str!("../licenses/GPL-3.0.txt");
const THIRD_PARTY: &str = include_str!("../THIRD-PARTY-NOTICES.txt");

/// The whole `ferx --licenses` text.
pub(crate) fn text() -> String {
    let rule = "=".repeat(78);
    let section = |title: &str, body: &str| format!("\n{rule}\n{title}\n{rule}\n{body}");
    let mut out = SUMMARY.replace("{version}", env!("CARGO_PKG_VERSION"));
    out += &section("MIT License (ferx-core, ferx-tools, ferx-cli)", MIT);
    out += &section("GNU Lesser General Public License, version 3 (ferx-search)", LGPL_3);
    out += &section("GNU General Public License, version 3 (ferx-search)", GPL_3);
    out += &section("Third-party notices", THIRD_PARTY);
    out
}

#[cfg(test)]
mod tests {
    #[test]
    fn licenses_text_carries_every_license_and_the_rebuild_recipe() {
        let text = super::text();
        let version = env!("CARGO_PKG_VERSION");
        for needle in [
            "Permission is hereby granted, free of charge",
            "GNU LESSER GENERAL PUBLIC LICENSE\n                       Version 3",
            "GNU GENERAL PUBLIC LICENSE\n                       Version 3",
            "Version 2.1, February 1999",
            "Parts of this crate follow the behaviour of Pharmpy",
            "src/algs/luksan",
            "cargo build --release --locked -p ferx-cli",
            &format!("git tag v{version}"),
        ] {
            assert!(text.contains(needle), "`ferx --licenses` lacks {needle:?}");
        }
        assert!(!text.contains("{version}"), "an unfilled {{version}} placeholder");
    }
}
